"""
BF16 GEMV: y = W @ x where x[K], W[N,K] → y[N]
Initial CUDA translation from Triton source
"""
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <cuda.h>
#include <cuda_bf16.h>
#include <cuda_fp16.h>

// Vector type for BF16 loads
struct bf16_4 {
    __nv_bfloat162 x;
    __nv_bfloat162 y;
};

__device__ __forceinline__ float bf16_to_float(__nv_bfloat16 val) {
    return __bfloat162float(val);
}

__device__ __forceinline__ float2 bf16x2_to_float2(__nv_bfloat162 val) {
    return __bfloat1622float2(val);
}

__global__ void gemv_kernel(
    const __nv_bfloat16* __restrict__ x,    // [K]
    const __nv_bfloat16* __restrict__ W,   // [N, K]
    float* __restrict__ y,                  // [N]
    const int N,
    const int K
) {
    const int BLOCK_N = 32;
    const int BLOCK_K = 512;
    const int NUM_WARPS = 8;
    const int WARP_SIZE = 32;
    const int THREADS_PER_BLOCK = NUM_WARPS * WARP_SIZE; // 256 threads

    // Shared memory for vector x chunk
    __shared__ __nv_bfloat16 x_shared[BLOCK_K];

    // Thread and block indices
    const int tid = threadIdx.x;
    const int block_id = blockIdx.x;

    // Which output elements this block handles
    const int n_start = block_id * BLOCK_N;

    // Each thread handles one or more output elements
    // 256 threads / 32 outputs = 8 threads per output
    const int threads_per_output = THREADS_PER_BLOCK / BLOCK_N;
    const int local_n = tid / threads_per_output;  // 0-31
    const int lane_in_group = tid % threads_per_output;  // 0-7

    // Global row index
    const int row = n_start + local_n;
    const bool row_valid = row < N;

    // Accumulator for this thread's partial sum
    float partial_sum = 0.0f;

    // Loop over K dimension in chunks of BLOCK_K
    const int num_chunks = (K + BLOCK_K - 1) / BLOCK_K;

    for (int chunk = 0; chunk < num_chunks; chunk++) {
        const int k_start = chunk * BLOCK_K;
        const int k_end = min(k_start + BLOCK_K, K);
        const int chunk_size = k_end - k_start;

        // Cooperative load of x chunk into shared memory
        // Vectorized loads using float4 (8 bf16 values at a time)
        const int vec_size = 8;
        const int num_vec_loads = (chunk_size + vec_size - 1) / vec_size;

        for (int i = tid; i < num_vec_loads; i += THREADS_PER_BLOCK) {
            const int k = k_start + i * vec_size;
            if (k + vec_size <= K) {
                float4* x_ptr = (float4*)(x + k);
                float4 x_val = *x_ptr;
                ((float4*)(x_shared + i * vec_size))[0] = x_val;
            } else {
                // Handle boundary
                for (int j = 0; j < vec_size && k + j < K; j++) {
                    x_shared[i * vec_size + j] = x[k + j];
                }
            }
        }

        __syncthreads();

        // Each thread computes partial sum over its assigned k range
        // Total k range per output: chunk_size
        // Each thread in group handles: chunk_size / threads_per_output
        const int k_per_thread = (chunk_size + threads_per_output - 1) / threads_per_output;
        const int my_k_start = lane_in_group * k_per_thread;
        const int my_k_end = min(my_k_start + k_per_thread, chunk_size);

        if (row_valid) {
            for (int k = my_k_start; k < my_k_end; k++) {
                __nv_bfloat16 x_val = x_shared[k];
                __nv_bfloat16 w_val = W[row * K + k_start + k];
                partial_sum += bf16_to_float(x_val) * bf16_to_float(w_val);
            }
        }

        __syncthreads();
    }

    // Reduce within each output group using warp shuffles
    // We have 8 threads per output, need to sum their partial_sums
    // Threads for the same output are at positions: local_n * 8 + lane_in_group

    // Warp-level reduction
    #pragma unroll
    for (int offset = threads_per_output / 2; offset > 0; offset >>= 1) {
        // Need to mask so we only reduce within the same output group
        // This is tricky with warp shuffles...
        // Simpler: use shared memory for reduction
    }

    __shared__ float reduce_shared[BLOCK_N][THREADS_PER_BLOCK / BLOCK_N + 1];

    if (row_valid) {
        reduce_shared[local_n][lane_in_group] = partial_sum;
    }
    __syncthreads();

    // Thread 0 in each group does the final sum
    if (lane_in_group == 0 && row_valid) {
        float sum = 0.0f;
        for (int i = 0; i < threads_per_output; i++) {
            sum += reduce_shared[local_n][i];
        }
        y[row] = sum;
    }
}

torch::Tensor gemv_cuda(torch::Tensor x, torch::Tensor W) {
    const int K = x.size(0);
    const int N = W.size(0);

    auto y = torch::empty({N}, torch::TensorOptions().dtype(torch::kFloat32).device(x.device()));

    const int BLOCK_N = 32;
    const int THREADS = 256;

    const int blocks = (N + BLOCK_N - 1) / BLOCK_N;

    gemv_kernel<<<blocks, THREADS>>>(
        (__nv_bfloat16*)x.data_ptr(),
        (__nv_bfloat16*)W.data_ptr(),
        y.data_ptr<float>(),
        N, K
    );

    return y;
}
"""

