    return __bfloat162float(val);
}

__device__ __forceinline__ float bf16x2_to_float(__nv_bfloat162 val) {
    float2 f2 = __bfloat1622float2(val);
    return f2.x + f2.y;  // Quick horizontal add
}

__global__ void gemv_kernel(
    const __nv_bfloat16* __restrict__ x,    // [K]
    const __nv_bfloat16* __restrict__ W,   // [N, K]
    float* __restrict__ y,                  // [N]
    const int N,
    const int K
) {
    // Each warp (32 threads) handles 1 row
    // Thread block has 8 warps = 256 threads = 8 rows per block
    const int WARP_SIZE = 32;
    const int NUM_WARPS = 8;

    const int warp_id = threadIdx.x / WARP_SIZE;
    const int lane_id = threadIdx.x % WARP_SIZE;
    const int row = blockIdx.x * NUM_WARPS + warp_id;

    // Vectorized loads: each thread loads 16 bf16 values at once
    // Using float4 = 128 bits = 8 bf16 values
    const int VEC_K = 16;  // bf16 values per thread per iteration
    const int K_STRIDE = WARP_SIZE * VEC_K;  // K elements covered by warp per iteration

    float sum = 0.0f;

    if (row < N) {
        // Main loop with vectorized loads
        const int full_iters = K / K_STRIDE;
        const __nv_bfloat16* W_row = W + row * K;

        for (int i = 0; i < full_iters; i++) {
            const int k_base = i * K_STRIDE + lane_id * VEC_K;

            // Load 16 bf16 values from x and W
            // Using 2x float4 (8 bf16 each)
            const float4* x_ptr0 = (const float4*)(x + k_base);
            const float4* x_ptr1 = (const float4*)(x + k_base + 8);
            const float4* w_ptr0 = (const float4*)(W_row + k_base);
            const float4* w_ptr1 = (const float4*)(W_row + k_base + 8);

            float4 xv0 = __ldg(x_ptr0);
            float4 xv1 = __ldg(x_ptr1);
            float4 wv0 = __ldg(w_ptr0);
            float4 wv1 = __ldg(w_ptr1);

            // Process 8 bf16 values from each float4
            // Each float4 contains 2x __nv_bfloat162 = 4 bf16
            // Actually float4 = 4 floats, not bf16. Need to reinterpret.
            __nv_bfloat16* x_bf0 = (__nv_bfloat16*)&xv0;
            __nv_bfloat16* x_bf1 = (__nv_bfloat16*)&xv1;
            __nv_bfloat16* w_bf0 = (__nv_bfloat16*)&wv0;
            __nv_bfloat16* w_bf1 = (__nv_bfloat16*)&wv1;

            #pragma unroll
            for (int j = 0; j < 8; j++) {
                sum += bf16_to_float(x_bf0[j]) * bf16_to_float(w_bf0[j]);
                sum += bf16_to_float(x_bf1[j]) * bf16_to_float(w_bf1[j]);
            }
        }

        // Handle remaining K elements
        const int k_remain = K % K_STRIDE;
        if (k_remain > 0) {
            const int k_base = full_iters * K_STRIDE;
            for (int k = lane_id; k < k_remain; k += WARP_SIZE) {
                sum += bf16_to_float(x[k_base + k]) * bf16_to_float(W_row[k_base + k]);
            }
        }
    }

    // Warp reduction using shuffle
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
    }

    // Lane 0 writes result
    if (lane_id == 0 && row < N) {
        y[row] = sum;
    }
}

