"""
BF16 GEMV: y = W @ x where x[K], W[N,K] → y[N]
Optimized with BF16 vector operations
"""
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <cuda.h>
#include <cuda_bf16.h>
#include <cuda_fp16.h>

// HMMA instruction wrappers for BF16
__device__ __forceinline__ float hmma_bf16_bf16_f32(
    unsigned A, unsigned B, float C) {
    float result;
    asm volatile(
        "mad.bf16.f32 %0, %1, %2, %3;\\n"
        : "=f"(result)
        : "h"((unsigned short)A), "h"((unsigned short)B), "f"(C)
