        cublasCreate(&handle);
    }
    ~CublasHandle() {
        cublasDestroy(handle);
    }
};

CublasHandle& get_cublas_handle() {
    static thread_local CublasHandle instance;
    return instance;
}

torch::Tensor gemv_cuda(torch::Tensor x, torch::Tensor W) {
    const int K = x.size(0);
    const int N = W.size(0);

    // Output as float32
    auto y = torch::empty({N}, torch::TensorOptions().dtype(torch::kFloat32).device(x.device()));

    cublasHandle_t handle = get_cublas_handle().handle;

    // cuBLAS uses column-major, but our data is row-major
    // W @ x = (row-major) -> need to use cubSgemv with transposition
    // Or use cublasGemmEx with appropriate layout

    // For row-major: W[N,K] @ x[K] = y[N]
    // In column-major: this is x^T @ W^T
    // y^T = x^T @ W^T, so y[i] = sum_j x[j] * W[i,j]

    // Use cublasGemmEx for BF16
    // gemm: C = alpha * op(A) * op(B) + beta * C
    // We want y = W * x
    // If W is N*K, x is K*1, y is N*1
    // In column-major: treat as W^T @ x (but x is Kx1, not 1xK)

    // Actually, for row-major storage interpreted as column-major:
    // A(m,n) row-major = A^T(n,m) column-major
    // W[N,K] row-major = W^T[K,N] column-major
    // So we want: y = W * x in row-major
    // = y_col = W_col^T * x_col = (KxN) * (Kx1) ???

    // Simpler: use cublasSgemv with transposition
    // cublasSgemv: y = alpha * op(A) * x + beta * y
    // op(A) can be transposed
    // If A is stored column-major as KxN (which is W^T from row-major NxK)
    // We want y = W * x = A^T * x
    // So use CUBLAS_OP_T

    const float alpha = 1.0f;
    const float beta = 0.0f;

    // W is NxK in row-major, so it's KxN in column-major
    // We want y = W * x, which in column-major terms is:
    // y = W_rowmaj * x = (W_colmaj)^T * x
    // So A = W, op(A) = T, A is KxN in col-major

    cublasStatus_t status = cublasGemmEx(
        handle,
        CUBLAS_OP_T,        // op(A) = A^T
        CUBLAS_OP_N,        // op(B) = B
        N,                  // m = rows of op(A) = cols of A = N
        1,                  // n = cols of op(B) = 1
        K,                  // k = cols of op(A) = rows of A = K
        &alpha,
        W.data_ptr(), CUDA_R_16BF, K,    // A is KxN in col-major (NxK row-major)
        x.data_ptr(), CUDA_R_16BF, K,    // B is Kx1 in col-major
        &beta,
        y.data_ptr<float>(), CUDA_R_32F, N,  // C is Nx1 in col-major
        CUBLAS_COMPUTE_32F,
        CUBLAS_GEMM_DEFAULT_TENSOR_OP
    );

    if (status != CUBLAS_STATUS_SUCCESS) {
        printf("cuBLAS error: %d\\n", status);
    }

    return y;
}
